        for i, row in enumerate(g):
            j = 0
            while j < len(row):
                if row[j] == col:
                    k = j
                    while k < len(row) and row[k] == col: k += 1
                    if k - j >= 2: out.append(('h', i, j, k - 1))
                    j = k
                else: j += 1
        for j in range(len(g[0])):
            i = 0
            while i < len(g):
                if g[i][j] == col:
                    k = i
                    while k < len(g) and g[k][j] == col: k += 1
                    if k - i >= 2: out.append(('v', j, i, k - 1))
                    i = k
                else: i += 1
        return out
    seg_col = None; marks = []
    for c in others:
        rr = runs(g, c)
        if rr: seg_col = c
        else: marks.append(c)
