    mark_col = marks[0]
    pts = [(i, j) for i in range(h) for j in range(w) if g[i][j] == mark_col]
    out = [row[:] for row in g]
    def fill_row(r, c1, c2, col):
        for j in range(min(c1, c2) + 1, max(c1, c2)):
            out[r][j] = col
