                else: fill_row(r, c, colB, mark_col)
                out[r][c] = 4
            u = sa if unmarked == 'A' else sb
            uc, u0, u1 = u[1], u[2], u[3]
            mr0 = rA0 if marked else rB0
            offs = sorted({r - mr0 for (r, c) in pts})
