def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def color_counts(grid):
    """Colors sorted by descending frequency, most common first."""
    return [c for c, _ in Counter(v for row in grid for v in row).most_common()]


def cells_of(grid, color):
    """All (row, col) positions of a color."""
    return [(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == color]


def vsegments(grid, color, minlen=2):
    """Maximal vertical runs of a color of length >= minlen, as [col, top, bottom]."""
    h, w = len(grid), len(grid[0])
    out = []
    for j in range(w):
        i = 0
        while i < h:
            if grid[i][j] == color:
                k = i
                while k < h and grid[k][j] == color:
                    k += 1
                if k - i >= minlen:
                    out.append([j, i, k - 1])
                i = k
            else:
                i += 1
    return out


def hsegments(grid, color, minlen=2):
    """Maximal horizontal runs of a color of length >= minlen, as [row, left, right]."""
    h, w = len(grid), len(grid[0])
    out = []
    for i in range(h):
        j = 0
        while j < w:
            if grid[i][j] == color:
                k = j
